changeSet.sql:
-- Явно выключенные функции (матрица уместности, план 2026-08-17 §4.2): UPDATE HUNTTECH_AI_FUNCTION_CONFIGURATION SET INCLUDE_USER_CONTEXT = FALSE WHERE INCLUDE_USER_CONTEXT IS NULL AND CODE IN ('STANDARDIZE_VACANCY','SKILLS_EXTRACT','TEXT_SMART_FORMAT_HTML', 'TEXT_SMART_FORMAT_PLAIN','PROJECT_DESCRIPTION_GENERATE', 'PROJECT_SHORT_DESCRIPTION_GENERATE','PROJECT_LOGO_IMAGE_GENERATE', 'TEST_CONNECTION');
-- Остальные текстовые функции (включая legacy vacancy-артефакты VACANCY_*) — TRUE: UPDATE HUNTTECH_AI_FUNCTION_CONFIGURATION SET INCLUDE_USER_CONTEXT = TRUE WHERE INCLUDE_USER_CONTEXT IS NULL AND CAPABILITY IN ('TEXT_GENERATION','TEXT_ANALYSIS','TEXT_TRANSFORMATION','DOCUMENT_ANALYSIS');
-- Все прочие (IMAGE и т.п.) — FALSE: UPDATE HUNTTECH_AI_FUNCTION_CONFIGURATION SET INCLUDE_USER_CONTEXT = FALSE WHERE INCLUDE_USER_CONTEXT IS NULL;
